  { _id: orderId, isPaid: false },  // guard: only update unpaid orders
  { $set: { isPaid: true, paidAt: new Date(), paymentResult: captureData } }
);
if (result.modifiedCount === 0) {
  // Order was already paid — idempotent no-op
}
